1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export interface InsuredItem {
11	  type: string;
12	  material?: string;
13	  enchantment?: number;
14	  cursed?: boolean;
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	/** A request to price a set of items. Becomes a policy the claims refer back to. */
28	export interface QuoteStep {
29	  op: "quote";
30	  items: InsuredItem[];
31	}
32	
33	/** A claim against an earlier quote step, identified by its index. */
34	export interface ClaimStep {
35	  op: "claim";
36	  policy: number;
37	  incident: Incident;
38	}
39	
40	/**
41	 * The two things a scenario can ask for. Discriminating on `op` lets the
42	 * compiler guarantee a claim has an incident and a quote has items, so
43	 * neither dispatch arm needs a non-null assertion or a defaulted field.
44	 */
45	export type Step = QuoteStep | ClaimStep;
46	
47	export interface QuoteResult {
48	  premium: number;
49	}
50	
51	export interface ClaimResult {
52	  payout: number;
53	  remainingCap: number;
54	}
55	
56	export type StepResult = QuoteResult | ClaimResult;
57	
58	export interface ScenarioResults {
59	  results: StepResult[];
60	}
61	
62	const BASE_PREMIUMS: Record<string, number> = {
63	  sword: 100,
64	  amulet: 60,
65	  staff: 80,
66	  potion: 40,
67	  rune: 25,
68	  moonstone: 25,
69	};
70	
71	const INSURANCE_VALUES: Record<string, number> = {
72	  sword: 1000,
73	  amulet: 600,
74	  staff: 800,
75	  potion: 400,
76	  rune: 250,
77	  moonstone: 250,
78	};
79	
80	const PROCESSING_FEE = 5;
81	
82	const WHOLE_PERCENT = 100;
83	
84	/**
85	 * Adjusts an amount by a percentage. A positive percent is a surcharge, a
86	 * negative one a discount.
87	 *
88	 * Multiplying before dividing keeps the arithmetic exact. A 1.1 multiplier
89	 * would not: floating-point `100 * 1.1` is 110.00000000000001, which rounds
90	 * up to 111 and yields a 116 G premium instead of 115 G.
91	 */
92	const adjustByPercent = (amount: number, percent: number): number =>
93	  (amount * (WHOLE_PERCENT + percent)) / WHOLE_PERCENT;
94	
95	/** All rounding is in the MHPCO's favor — always up. */
96	const roundInMHPCOsFavor = Math.ceil;
97	
98	const BUILDING_BLOCK_SIZE = 3;
99	const BUILDING_BLOCK_PREMIUM = 60;
100	
101	/** Item kinds are compared by type — both grouping and claims match on it. */
102	const isOfType =
103	  (type: string) =>
104	  (item: InsuredItem): boolean =>
105	    item.type === type;
106	
107	/** Only items of one and the same kind group into a block. */
108	const areAllTheSameKind = ([first, ...rest]: InsuredItem[]): boolean =>
109	  first !== undefined && rest.every(isOfType(first.type));
110	
111	/**
112	 * How many flat-rate blocks this list forms. A mixed list forms none — only
113	 * alike items group — and so does any list too short to fill one block.
114	 */
115	const countCompleteBlocks = (items: InsuredItem[]): number =>
116	  areAllTheSameKind(items) ? Math.floor(items.length / BUILDING_BLOCK_SIZE) : 0;
117	
118	const CURSED_SURCHARGE_PERCENT = 50;
119	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
120	
121	/**
122	 * Enchantment drives two unrelated rules at two different levels, so each
123	 * threshold is named for the rule it belongs to rather than for the adjective
124	 * the spec happens to use. Level 5 makes an item dearer to insure; level 8
125	 * makes damage to it cheaper to reimburse. Neither level should ever be
126	 * substituted for the other.
127	 */
128	const SURCHARGEABLE_ENCHANTMENT_LEVEL = 5;
129	
130	/** A risk rule contributes its percent only when the item trips it. */
131	const percentWhen = (applies: boolean, percent: number): number =>
132	  applies ? percent : 0;
133	
134	const enchantmentOf = (item: InsuredItem): number => item.enchantment ?? 0;
135	
136	const attractsEnchantmentSurcharge = (item: InsuredItem): boolean =>
137	  enchantmentOf(item) >= SURCHARGEABLE_ENCHANTMENT_LEVEL;
138	
139	/** Risk surcharges add to the base premium; they do not compound. */
140	const riskSurchargePercentFor = (item: InsuredItem): number =>
141	  percentWhen(item.cursed === true, CURSED_SURCHARGE_PERCENT) +
142	  percentWhen(
143	    attractsEnchantmentSurcharge(item),
144	    HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
145	  );
146	
147	/** An item's list price with its own risk surcharges applied. */
148	const riskAdjustedPremiumFor = (item: InsuredItem): number =>
149	  adjustByPercent(BASE_PREMIUMS[item.type], riskSurchargePercentFor(item));
150	
151	/**
152	 * Prices an item list: alike items are grouped into building blocks sold at a
153	 * flat rate, and whatever is left over is priced item by item, each at its own
154	 * risk-adjusted premium.
155	 */
156	const priceItems = (items: InsuredItem[]): number => {
157	  const blocks = countCompleteBlocks(items);
158	  const leftovers = items.slice(blocks * BUILDING_BLOCK_SIZE);
159	
160	  return (
161	    blocks * BUILDING_BLOCK_PREMIUM +
162	    leftovers.reduce((sum, item) => sum + riskAdjustedPremiumFor(item), 0)
163	  );
164	};
165	
166	/** Discounts are negative adjustments — long-standing customers pay 20% less. */
167	const LOYALTY_DISCOUNT_PERCENT = -20;
168	const LOYALTY_YEARS = 2;
169	const REPEAT_CONTRACT_DISCOUNT_PERCENT = -15;
170	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
171	
172	const isLongStanding = (customer: Customer): boolean =>
173	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
174	
175	/** The first contract is assessed; every later one earns a discount instead. */
176	const contractPercentFor = (isFirstContract: boolean): number =>
177	  isFirstContract
178	    ? FIRST_INSURANCE_SURCHARGE_PERCENT
179	    : REPEAT_CONTRACT_DISCOUNT_PERCENT;
180	
181	/**
182	 * The customer's own standing modifies the item price. Unlike the risk
183	 * surcharges, which add up before being applied once, these modifiers
184	 * COMPOUND: each applies to the result of the last. A 20% discount followed
185	 * by a 10% surcharge is 100 -> 80 -> 88, not 100 -> 90.
186	 */
187	const applyCustomerModifiers = (
188	  price: number,
189	  customer: Customer,
190	  isFirstContract: boolean,
191	): number => {
192	  const afterLoyalty = adjustByPercent(
193	    price,
194	    percentWhen(isLongStanding(customer), LOYALTY_DISCOUNT_PERCENT),
195	  );
196	
197	  return adjustByPercent(afterLoyalty, contractPercentFor(isFirstContract));
198	};
199	
200	/**
201	 * The premium pipeline, in the order the spec states it: price the items,
202	 * apply the customer's modifiers, round, then add the processing fee last.
203	 */
204	const quotePremium = (
205	  items: InsuredItem[],
206	  customer: Customer,
207	  isFirstContract: boolean,
208	): QuoteResult => ({
209	  premium:
210	    roundInMHPCOsFavor(
211	      applyCustomerModifiers(priceItems(items), customer, isFirstContract),
212	    ) + PROCESSING_FEE,
213	});
214	
215	/**
216	 * Contracts are counted by quote step, not by step position — a scenario may
217	 * open with a claim, and the quote that follows is still the customer's first
218	 * contract.
219	 */
220	const FIRST_CONTRACT = 1;
221	
222	const DEDUCTIBLE = 100;
223	const CAP_MULTIPLE = 2;
224	
225	const insuranceSumOf = (items: InsuredItem[]): number =>
226	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
227	
228	/**
229	 * Stands in for a damage whose item type the policy does not list. Its bare
230	 * attributes trip no rate rule, so such a damage reimburses in full.
231	 */
232	const UNCOVERED_ITEM: InsuredItem = { type: "" };
233	
234	/** See SURCHARGEABLE_ENCHANTMENT_LEVEL — a different rule at a different level. */
235	const HALVING_ENCHANTMENT_LEVEL = 8;
236	const HALF = 0.5;
237	const IN_FULL = 1;
238	
239	const DRAGON_MATERIAL = "dragon";
240	
241	const isDragonMade = (item: InsuredItem): boolean =>
242	  item.material === DRAGON_MATERIAL;
243	
244	/** The mirror of attractsEnchantmentSurcharge, at the halving rule's level. */
245	const attractsEnchantmentHalving = (item: InsuredItem): boolean =>
246	  enchantmentOf(item) >= HALVING_ENCHANTMENT_LEVEL;
247	
248	/**
249	 * Damage to an item enchanted this far is only half reimbursed — unless it is
250	 * dragon-made, which the MHPCO always makes good in full whatever else is true
251	 * of the item. Dragon material is checked first because it overrides halving,
252	 * not the other way round.
253	 */
254	const reimbursementRateFor = (item: InsuredItem): number =>
255	  attractsEnchantmentHalving(item) && !isDragonMade(item) ? HALF : IN_FULL;
256	
257	/**
258	 * The damaged item's entry in the policy. A damage naming something the policy
259	 * does not cover reimburses in full — no rate rule can trip without an item to
260	 * read it from.
261	 */
262	const damagedItemIn = (
263	  damage: Damage,
264	  insuredItems: InsuredItem[],
265	): InsuredItem => insuredItems.find(isOfType(damage.itemType)) ?? UNCOVERED_ITEM;
266	
267	const reimbursableAmountOf = (
268	  damage: Damage,
269	  insuredItems: InsuredItem[],
270	): number =>
271	  damage.amount * reimbursementRateFor(damagedItemIn(damage, insuredItems));
272	
273	/** One incident is one deductible, so the damages are totalled before it applies. */
274	const totalDamageOf = (
275	  incident: Incident,
276	  insuredItems: InsuredItem[],
277	): number =>
278	  incident.damages.reduce(
279	    (sum, damage) => sum + reimbursableAmountOf(damage, insuredItems),
280	    0,
281	  );
282	
283	/** The MHPCO never owes a negative amount; below the deductible it owes nothing. */
284	const OWES_NOTHING = 0;
285	
286	/**
287	 * What the incident itself puts the MHPCO on the hook for. The customer bears
288	 * the deductible, so only the damage above it is owed — and an incident that
289	 * stays within the deductible is owed nothing rather than turning the shortfall
290	 * into a debt.
291	 *
292	 * This is the incident's own figure, taking no account of the policy it is
293	 * claimed against. What the policy can actually pay out is a separate question,
294	 * answered by `limitedByRemainingCover`.
295	 */
296	const amountOwedFor = (
297	  incident: Incident,
298	  insuredItems: InsuredItem[],
299	): number =>
300	  Math.max(OWES_NOTHING, totalDamageOf(incident, insuredItems) - DEDUCTIBLE);
301	
302	/**
303	 * What the policy can still pay, whatever the incident owes. Cover is a finite
304	 * pot shared by every claim on the policy, so a claim is paid only as far as
305	 * the pot reaches.
306	 *
307	 * The counterpart of the deductible floor in `amountOwedFor`: that one bounds
308	 * the incident from below, this one bounds the policy from above. Two separate
309	 * rules, so two separate names.
310	 */
311	const limitedByRemainingCover = (
312	  amountOwed: number,
313	  remainingCover: number,
314	): number => Math.min(amountOwed, remainingCover);
315	
316	const settleClaim = (
317	  incident: Incident,
318	  insuredItems: InsuredItem[],
319	  capBefore: number,
320	): ClaimResult => {
321	  const payout = limitedByRemainingCover(
322	    amountOwedFor(incident, insuredItems),
323	    capBefore,
324	  );
325	
326	  return { payout, remainingCap: capBefore - payout };
327	};
328	
329	/** A policy's total cover: twice the insurance sum, shared by all its claims. */
330	const capOf = (insuredItems: InsuredItem[]): number =>
331	  CAP_MULTIPLE * insuranceSumOf(insuredItems);
332	
333	/**
334	 * A claim names the quote step it is made against; the items on that step are
335	 * the ones the policy covers.
336	 */
337	const itemsCoveredBy = (claim: ClaimStep, steps: Step[]): InsuredItem[] => {
338	  const policy = steps[claim.policy];
339	
340	  return policy.op === "quote" ? policy.items : [];
341	};
342	
343	/**
344	 * The running cover left on each policy, keyed by the quote step that opened
345	 * it. A policy absent from the ledger has not been claimed against yet, so its
346	 * remaining cover is still the full cap.
347	 */
348	type CapLedger = Map<number, number>;
349	
350	/**
351	 * Settles one claim against the ledger and draws the payout down from the
352	 * policy's remaining cover. This is the one step kind whose result depends on
353	 * the steps before it, so it is also the only one that writes to the ledger.
354	 */
355	const settleClaimAgainstLedger = (
356	  claim: ClaimStep,
357	  steps: Step[],
358	  remainingCaps: CapLedger,
359	): ClaimResult => {
360	  const insuredItems = itemsCoveredBy(claim, steps);
361	  const capBefore = remainingCaps.get(claim.policy) ?? capOf(insuredItems);
362	  const result = settleClaim(claim.incident, insuredItems, capBefore);
363	
364	  remainingCaps.set(claim.policy, result.remainingCap);
365	
366	  return result;
367	};
368	
369	/**
370	 * Works the scenario's steps in order, returning one result per step.
371	 *
372	 * The traversal is a `for...of` rather than a `map` because it is genuinely
373	 * order-dependent: each claim draws down a cap that later claims on the same
374	 * policy read back. `map` would compute the same answers — it runs
375	 * left-to-right — but it advertises an independent per-element transform, and
376	 * this is not one. The loop states the sequencing the cap ledger relies on.
377	 */
378	export const runScenario = ({
379	  customer,
380	  steps,
381	}: Scenario): ScenarioResults => {
382	  const remainingCaps: CapLedger = new Map();
383	  const results: StepResult[] = [];
384	  let contractsSoFar = 0;
385	
386	  for (const step of steps) {
387	    if (step.op === "quote") {
388	      contractsSoFar += 1;
389	      results.push(
390	        quotePremium(step.items, customer, contractsSoFar === FIRST_CONTRACT),
391	      );
392	    } else {
393	      results.push(settleClaimAgainstLedger(step, steps, remainingCaps));
394	    }
395	  }
396	
397	  return { results };
398	};
