  customer,
  steps,
}: Scenario): ScenarioResults => {
  const remainingCaps: CapLedger = new Map();
  const results: StepResult[] = [];
  let contractsSoFar = 0;

  for (const step of steps) {
    if (step.op === "quote") {
      contractsSoFar += 1;
      results.push(
        quotePremium(step.items, customer, contractsSoFar === FIRST_CONTRACT),
      );
    } else {
      results.push(settleClaimAgainstLedger(step, steps, remainingCaps));
    }
  }

  return { results };
};

